  "questions": [
    {
      "id": "q1",
      "type": "single",
      "text": "Where should the base branch setting live?",
      "options": [
        "On each pipeline — one setting per pipeline that applies to all of its tasks",
        "On each stage individually",
        "Both — a pipeline-level default that individual stages can override"
      ],
      "required": true,
      "showIf": null
    },
    {
      "id": "q2",
      "type": "single",
      "text": "What should a pipeline's base branch control?",
      "options": [
        "Both — new task branches are created from it, and the merge stage merges back into it",
        "Only where new task branches are created from",
        "Only where the merge stage merges into"
      ],
      "required": true,
      "showIf": null
    },
    {
      "id": "q3",
      "type": "single",
      "text": "If the configured branch does not exist in the repository yet, what should happen when a task is created in that pipeline?",
      "options": [
        "Show a clear error asking the user to create the branch first",
        "Automatically create it from the repo's current default branch (e.g. main)",
        "Silently fall back to the repo's default branch"
      ],
      "required": true,
      "showIf": null
    },
    {
      "id": "q4",
      "type": "single",
      "text": "If you change a pipeline's base branch while tasks are already running in that pipeline, what should those existing tasks do?",
      "options": [
        "Keep using the base branch that was set when each task was created",
        "Switch to the pipeline's newly configured base branch"
      ],
      "required": true,
      "showIf": null
    },
    {
      "id": "q5",
      "type": "single",
      "text": "Where should this setting be editable?",
      "options": [
        "In the UI, in the pipeline settings (the workflow management panel)",
        "Only in the project config file for now",
        "Either is fine"
      ],
      "required": true,
      "showIf": null
    },
    {
      "id": "q6",
      "type": "single",
      "text": "Test/CI stages can optionally run directly on the main branch instead of the task branch. In a pipeline with a custom base branch, should that mode use the pipeline's base branch too?",
      "options": [
        "Yes — inside such a pipeline, 'the main branch' means the pipeline's configured base branch",
        "No — it always means the repo's real default branch (main/master)"
      ],
      "required": true,
      "showIf": null
    },
    {
      "id": "q7",
      "type": "single",
      "text": "What should we call this setting in the UI?",
      "options": [
        "Base branch",
        "Main branch",
        "Integration branch",
        "Target branch"
      ],
      "required": false,
      "showIf": null
    },
    {
      "id": "q8",
      "type": "multiple",
      "text": "Anything else that should follow the pipeline's base branch? (pick all that apply)",
      "options": [
        "After a merge, push the base branch to the remote so the feature branch is updated on the server",
        "The branch the runner switches back to after each stage finishes",
        "Review/diff views that compare the task's work against the base branch",
        "Nothing else — only task branch creation and merging"
      ],
      "required": false,
      "showIf": null
    }
  ],
  "answers": {
    "q1": {
      "selected": [
        "On each pipeline — one setting per pipeline that applies to all of its tasks"
      ],
      "notes": ""
    },
    "q2": {
      "selected": [
        "Both — new task branches are created from it, and the merge stage merges back into it"
      ],
      "notes": ""
    },
    "q3": {
