/***
 * MARK: Create Named Workflow for Project
 ***/
app.post("/projects/:id/workflows", async (request, reply) => {
	const project = projectStore.getProject(request.params.id);
	if (!project) return reply.status(404).send({ error: "Project not found" });

	const { name, stages, isDefault, baseBranch } = request.body || {};
	if (!name || typeof name !== "string" || !name.trim()) {
		return reply.status(400).send({ error: "Workflow name is required" });
	}

	const policyError = assertValidStageRunnerPolicies(stages);
	if (policyError) return reply.status(400).send(policyError);
	const workflowAutoApproveError = assertValidStageAutoApproves(stages);
	if (workflowAutoApproveError) return reply.status(400).send(workflowAutoApproveError);

	try {
		const workflow = projectStore.createWorkflow(request.params.id, {
			name,
			stages,
			isDefault,
			baseBranch,
		});
		return reply.status(201).send(workflow);
	} catch (err) {
		return reply.status(400).send({ error: err.message });
	}
});

/***
 * MARK: Switch Active Workflow for Project
 ***/
