		if (branchName.startsWith("kb/")) {
			const branchTaskSegment = branchName.slice("kb/".length);
			if (branchTaskSegment.trim() === "") return null;
			return sanitizeTaskId(branchTaskSegment);
		}
	}
	return null;
}

